package service;

import domain.Member;
import infra.PtsctlClient;

import java.util.regex.Pattern;

/**
 * Customer-care compensation: credited at the vendor under its own reference (A-<ticket>), so it
 * shows in the member's balance and history but is not an earn: it never enters our earn ledger
 * (which feeds the monthly top-earners ranking) and is not matched against the payment reconciliation.
 * The vendor rejects a reference it has already seen, so one ticket pays at most once.
 */
public class CompensationService {
    private static final String REF_PREFIX = "A-";
    /** The vendor allows [A-Za-z0-9-] up to 32 characters in a reference. */
    private static final Pattern TICKET = Pattern.compile("[A-Za-z0-9-]{1,29}");

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Returns the vendor entry number. Refuses before calling the vendor if anything is wrong. */
    public String compensate(String memberNo, long points, String ticketNo) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        if (points <= 0) throw new IllegalArgumentException("compensation points must be positive: " + points);
        if (ticketNo == null || !TICKET.matcher(ticketNo).matches()) {
            throw new IllegalArgumentException("bad ticket number: " + ticketNo);
        }
        return pts.earn(m.memberNo(), points, REF_PREFIX + ticketNo);
    }
}

